-- MacroForge: applies macros defined in MacroForgeData.lua (generated by macroforge.py).
-- Matches by macro NAME: same name = edit in place, new name = create.
-- Only touches macros whose names appear in the data file; extra copies of those
-- (e.g. from earlier buggy runs) are deleted so each managed name exists once.
local SCAN_MAX = 300  -- generous upper bound on macro indices; unused slots return nil

local function say(msg) print("|cff66ccffMacroForge:|r " .. msg) end
MacroForgeCore = {}  -- entry points shared with the window (UI.lua)

-- The window's status line (UI.lua sets onStatus); note() also prints the same text in chat.
local function status(msg)
    if MacroForgeCore.onStatus then pcall(MacroForgeCore.onStatus, msg) end
end

local function note(msg)
    say(msg)
    status(msg)
end

-- Anything that came from a file (macro names, replies, error text) is shown with '|' doubled,
-- so it can never render colors, links or textures in the chat window.
local function plain(s) return (tostring(s):gsub("|", "||")) end

-- Data files are written by an outside program, so treat their contents as untrusted:
-- only use values of the expected type and size.
local function list(t) return type(t) == "table" and t or {} end

-- Saved variables are a file the player can edit: a counter that is not a number counts as 0.
local function counter(value) return type(value) == "number" and value or 0 end

local function validMacro(m)
    return type(m) == "table"
        and type(m.name) == "string" and #m.name >= 1 and #m.name <= 64
        and type(m.body) == "string" and #m.body <= 255
        and type(m.icon) == "number" and m.icon == math.floor(m.icon)
        and (m.script == nil or type(m.script) == "boolean")
end

-- "Testy Mage", "Testy-Mage" and "testymage" all compare equal.
local function norm(s) return (tostring(s):lower():gsub("[^%w]", "")) end

-- Every spelling of this character's identity we can find. WoW Forever gives
-- characters surnames; where the client exposes that is not documented, so we
-- accept the first name, name+second return of UnitName/UnitFullName, and GetUnitName.
local function identity()
    local out, raw = {}, {}
    local function add(...)
        local name, extra = ...
        if type(name) == "string" and name ~= "" then
            raw[#raw + 1] = name
            out[norm(name)] = true
            if type(extra) == "string" and extra ~= "" then
                raw[#raw + 1] = name .. " " .. extra
                out[norm(name .. extra)] = true
            end
        end
    end
    pcall(function() add(UnitName("player")) end)
    pcall(function() add(UnitFullName("player")) end)
    pcall(function() add(GetUnitName("player", true)) end)
    return out, raw
end

-- Account macros vs character macros: GetMacroInfo's 4th return (isLocal) says
-- which; if a client omits it, fall back to the GetNumMacros() boundary.
local function scan()
    local numAccount = GetNumMacros()
    local account, char = {}, {}
    for i = 1, SCAN_MAX do
        local name, _, _, isLocal = GetMacroInfo(i)
        if name then
            if isLocal == nil then isLocal = i > numAccount end
            local bucket = isLocal and char or account
            bucket[name] = bucket[name] or {}
            table.insert(bucket[name], i)
        end
    end
    return account, char
end

-- The game stores macro bodies with a trailing newline, so compare without it
-- (comparing raw bodies made every macro look "changed" on every login).
local function trim(s) return (tostring(s or ""):gsub("%s+$", "")) end

-- Script macros (script = true in the data) hold `/run` lines of Lua. The Lua is compiled here,
-- never run, so a syntax error is reported now instead of when the macro is pressed.
local function scriptSyntaxError(body)
    for line in tostring(body):gmatch("[^\n]+") do
        local code = line:match("^%s*/run%s+(%S.*)$")
        if not code then return "every line of a script must start with /run" end
        if type(loadstring) == "function" then
            local fn, err = loadstring(code)
            if not fn then return err end
        end
    end
end

-- Blizzard shows its own warning the first time a custom script runs. Say so once, so it does not
-- come as a surprise, and say what MacroForge does about it (and does not promise).
MacroForgeCore.scriptNote = "Scripts run once when you press the macro. The first time, Blizzard "
    .. "shows its own custom-script warning; that is normal."

-- Blizzard remembers that you accepted its warning in the allowDangerousScripts setting ("1").
local function warningAccepted()
    local ok, value = pcall(GetCVar, "allowDangerousScripts")
    return ok and tostring(value) == "1"
end

local function scriptNotice()
    if warningAccepted() then return end  -- Blizzard's warning will not appear, nothing to explain
    if type(MacroForgeUI) ~= "table" then MacroForgeUI = {} end
    if MacroForgeUI.scriptNoticeSeen then return end
    MacroForgeUI.scriptNoticeSeen = true
    say("Script macro installed. The first time you press a script macro, Blizzard shows a warning "
        .. "(\"You are attempting to run a custom script...\").")
    say("That warning is Blizzard's and appears for every custom script, whoever wrote it. MacroForge "
        .. "checks each script before installing it and is designed to refuse anything that sends "
        .. "chat, touches items, gold, mail, trades or guilds, or repeats actions by itself. No check "
        .. "is perfect, so read what a script does before you accept the warning.")
end

-- What MacroForge has made (saved variable MacroForgeOwned), so that a macro you delete in the game
-- window stays deleted: `made[key]` is the icon and text we last put in the game, `told[key]` the one
-- we already announced as deleted by you, `removed[key]` a name the "remove" list has dealt with.
-- Keys say whose macro it is: "A:name" account-wide, "C:<character>:name" for one character.
local function owned()
    if type(MacroForgeOwned) ~= "table" then MacroForgeOwned = {} end
    for _, field in ipairs({ "made", "told", "removed" }) do
        if type(MacroForgeOwned[field]) ~= "table" then MacroForgeOwned[field] = {} end
    end
    return MacroForgeOwned
end

local function ownerKey(perChar, name)
    if not perChar then return "A:" .. name end
    local first, second = UnitName("player")
    return "C:" .. norm((first or "") .. ((second and second ~= "") and second or "")) .. ":" .. name
end

local function signature(m) return tostring(m.icon) .. "\n" .. trim(m.body) end

local function applyOne(m, perChar, stats, trigger)
    local account, char = scan()
    local found = (perChar and char or account)[m.name]
    local store, key = owned(), ownerKey(perChar, m.name)
    if found then
        local idx = found[1]
        local _, icon, body = GetMacroInfo(idx)
        if tonumber(icon) ~= m.icon or trim(body) ~= trim(m.body) then
            -- evidence log (kept across runs, capped) in case a difference is ever real
            if type(MacroForgeLog) ~= "table" then MacroForgeLog = {} end
            MacroForgeLog[#MacroForgeLog + 1] = {
                when = trigger, name = m.name, gameIcon = icon, ourIcon = m.icon,
                gameBody = body, ourBody = m.body,
            }
            while #MacroForgeLog > 20 do table.remove(MacroForgeLog, 1) end
            EditMacro(idx, m.name, m.icon, m.body)
            stats.updated = stats.updated + 1
            if m.script then stats.scripts = stats.scripts + 1 end
        end
        for k = #found, 2, -1 do  -- delete extras, highest index first
            DeleteMacro(found[k])
            stats.removed = stats.removed + 1
        end
        store.made[key], store.told[key] = signature(m), nil
    elseif store.made[key] == signature(m) then
        -- we made exactly this macro before and it is gone: you deleted it, so leave it deleted
        -- (it comes back only if its text or icon changes, e.g. you asked for a new version)
        if store.told[key] ~= store.made[key] then
            store.told[key] = store.made[key]
            stats.gone = stats.gone or {}
            stats.gone[#stats.gone + 1] = m.name
        end
    else
        local ok = pcall(CreateMacro, m.name, m.icon, m.body, perChar)
        if ok then
            stats.created = stats.created + 1
            if m.script then stats.scripts = stats.scripts + 1 end
            store.made[key], store.told[key] = signature(m), nil
        else stats.failed = stats.failed + 1; say("could not create '" .. plain(m.name) .. "' (slots full?)") end
    end
end

-- One bad entry must not stop the others: validate it, and run it under pcall.
local function applySafely(m, perChar, stats, trigger)
    if not validMacro(m) then
        stats.failed = stats.failed + 1
        say("skipped a malformed macro entry")
        return
    end
    if m.script then
        local problem = scriptSyntaxError(m.body)
        if problem then
            stats.failed = stats.failed + 1
            say("script '" .. plain(m.name) .. "' was not installed: " .. plain(problem))
            return
        end
    end
    local ok, err = pcall(applyOne, m, perChar, stats, trigger)
    if not ok then
        stats.failed = stats.failed + 1
        say("error applying '" .. plain(m.name) .. "': " .. plain(err))
    end
end

-- Delete macros the spec lists under "remove" (by name, in the given scope only).
local function removeByName(names, perChar, stats, keep)
    for _, name in ipairs(list(names)) do
        -- never delete a macro that this very run has just created or updated
        if type(name) == "string" and not (keep and keep[name]) then
            local account, char = scan()
            local found = (perChar and char or account)[name]
            local store, key = owned(), ownerKey(perChar, name)
            -- delete it if we made it, or if this is the first time the removal is applied; once it has
            -- been dealt with, a macro of the same name that you make yourself is left alone
            if found and (store.made[key] or not store.removed[key]) then
                for k = #found, 1, -1 do  -- highest index first so indices stay valid
                    if pcall(DeleteMacro, found[k]) then stats.removed = stats.removed + 1 end
                end
            end
            store.removed[key], store.made[key], store.told[key] = true, nil, nil
        end
    end
end

local appliedRev = 0  -- rev of the data last applied this session (login file or a live slot)

-- History: the requests this account has sent and the reply to each, newest last (saved variable
-- MacroForgeHistory, capped). The window's History panel reads it through MacroForgeCore.history().
local HISTORY_MAX, REPLY_MAX = 30, 600

local function historyStore()
    if type(MacroForgeHistory) ~= "table" then MacroForgeHistory = {} end
    return MacroForgeHistory
end

local function historyChanged()
    if MacroForgeCore.onHistory then pcall(MacroForgeCore.onHistory) end
end

local function recordRequest(id, mode, text, char)
    local store = historyStore()
    store[#store + 1] = { id = id, time = time(), mode = mode, text = text, char = char }
    while #store > HISTORY_MAX do table.remove(store, 1) end
    historyChanged()
end

local function recordReply(req, text)
    for _, entry in ipairs(historyStore()) do
        if type(entry) == "table" and entry.id == req and entry.reply ~= text:sub(1, REPLY_MAX) then
            entry.reply = text:sub(1, REPLY_MAX)
            historyChanged()
        end
    end
end

-- Newest first; rows of the wrong shape (the file is editable) are skipped.
function MacroForgeCore.history()
    local store, out = historyStore(), {}
    for i = #store, 1, -1 do
        local e = store[i]
        if type(e) == "table" and type(e.id) == "number" and type(e.text) == "string" then
            out[#out + 1] = { id = e.id, text = e.text, time = tonumber(e.time) or 0,
                              mode = (e.mode == "script") and "script" or "macro",
                              char = type(e.char) == "string" and e.char or "",
                              reply = type(e.reply) == "string" and e.reply or nil }
        end
    end
    return out
end

-- Replies from the PC-side watcher arrive inside the data files (data.replies). Show each once;
-- MacroForgeSeen remembers the newest reply id we have printed (saved variable).
function MacroForge_ShowReplies(data)
    MacroForgeSeen, MacroForgeAnswered = counter(MacroForgeSeen), counter(MacroForgeAnswered)
    local newest = MacroForgeSeen
    for _, r in ipairs(list(data.replies)) do
        if type(r) == "table" and type(r.id) == "number" and type(r.text) == "string" and not r.pending then
            if r.id > MacroForgeSeen then
                say("|cffffd100reply:|r " .. plain(r.text))
                if r.id > newest then newest = r.id end
            end
            if type(r.req) == "number" then recordReply(r.req, r.text) end
            if type(r.req) == "number" and r.req > MacroForgeAnswered then MacroForgeAnswered = r.req end
        end
    end
    MacroForgeSeen = newest
end

-- Requests we have sent that no reply has answered yet (shown at login as a reminder).
local function pendingRequests()
    local n = 0
    for _, q in ipairs(list(MacroForgeRequests)) do
        if type(q) == "table" and type(q.id) == "number" and q.id > counter(MacroForgeAnswered) then
            n = n + 1
        end
    end
    return n
end

local function applyAll(quiet, data, how)
    if InCombatLockdown() then say("in combat - try /mf after the fight"); return end
    data = data or MacroForgeData
    if type(data) ~= "table" then return end
    if type(data.rev) == "number" then appliedRev = data.rev end
    MacroForge_ShowReplies(data)
    local trigger = how or (quiet and "login" or "manual")
    local stats = { created = 0, updated = 0, removed = 0, failed = 0, scripts = 0 }
    local keepAccount, keepChar = {}, {}
    for _, m in ipairs(list(data.account)) do
        applySafely(m, false, stats, trigger)
        if type(m) == "table" then keepAccount[m.name] = true end
    end
    local me = identity()
    for key, macros in pairs(list(data.chars)) do
        if me[norm(key)] then
            for _, m in ipairs(list(macros)) do
                applySafely(m, true, stats, trigger)
                if type(m) == "table" then keepChar[m.name] = true end
            end
        end
    end
    local rm = list(data.remove)
    removeByName(rm.account, false, stats, keepAccount)
    for key, names in pairs(list(rm.chars)) do
        if me[norm(key)] then removeByName(names, true, stats, keepChar) end
    end
    -- forget macros that are no longer in the data (account-wide ones, and this character's own)
    local store, prefix = owned(), ownerKey(true, "")
    for key in pairs(store.made) do
        local account, mine = key:sub(1, 2) == "A:", key:sub(1, #prefix) == prefix
        local name = account and key:sub(3) or (mine and key:sub(#prefix + 1))
        if name and not (account and keepAccount[name] or mine and keepChar[name]) then
            store.made[key], store.told[key] = nil, nil
        end
    end
    local total = stats.created + stats.updated + stats.removed + stats.failed
    if not quiet or total > 0 then
        say(("%d created, %d updated, %d removed, %d failed"):format(
            stats.created, stats.updated, stats.removed, stats.failed))
    end
    if stats.gone then
        local names = {}
        for i, name in ipairs(stats.gone) do
            names[#names + 1] = (i <= 4) and ("'" .. plain(name) .. "'") or nil
        end
        local more = #stats.gone > 4 and (" and " .. (#stats.gone - 4) .. " more") or ""
        say(("You deleted %s%s in the game, so MacroForge will not bring %s back. It returns only "
             .. "if you ask for a new version of it."):format(table.concat(names, ", "), more,
                                                              #stats.gone == 1 and "it" or "them"))
    end
    if stats.scripts > 0 then scriptNotice() end
end

-- Dump the spellbook, macro table and identity to SavedVariables (written to disk
-- on /reload or logout) so macroforge.py / Claude can see what this character has.
local function exportAll(quiet)
    local spells = {}
    if C_SpellBook and C_SpellBook.GetNumSpellBookSkillLines then
        for t = 1, C_SpellBook.GetNumSpellBookSkillLines() do
            local line = C_SpellBook.GetSpellBookSkillLineInfo(t)
            for i = line.itemIndexOffset + 1, line.itemIndexOffset + line.numSpellBookItems do
                local it = C_SpellBook.GetSpellBookItemInfo(i, Enum.SpellBookSpellBank.Player)
                if it and it.spellID then
                    spells[#spells + 1] = { tab = line.name, name = it.name, id = it.spellID, passive = it.isPassive or false }
                end
            end
        end
    elseif GetNumSpellTabs then
        for t = 1, GetNumSpellTabs() do
            local tab, _, offset, count = GetSpellTabInfo(t)
            for i = offset + 1, offset + count do
                local name, rank = GetSpellBookItemName(i, "spell")
                local _, id = GetSpellBookItemInfo(i, "spell")
                if name then spells[#spells + 1] = { tab = tab, name = name, rank = rank, id = id } end
            end
        end
    end
    local numAccount, numChar = GetNumMacros()
    local macros = {}
    for i = 1, SCAN_MAX do
        local name, icon, _, isLocal = GetMacroInfo(i)
        -- the Forever client returns no 4th value, so fall back to the index boundary (as scan() does)
        if isLocal == nil then isLocal = i > numAccount end
        if name then macros[#macros + 1] = { index = i, name = name, icon = icon, isLocal = isLocal } end
    end
    local _, raw = identity()
    -- Current pet (summon it first): its name/family is what [pet:...] conditionals match,
    -- and its action bar lists the pet spells usable from macros.
    local pet
    if UnitExists("pet") then
        pet = { name = UnitName("pet"), family = UnitCreatureFamily("pet"), type = UnitCreatureType("pet"), actions = {} }
        if GetPetActionInfo then
            for i = 1, 10 do
                local ok, name = pcall(GetPetActionInfo, i)
                if ok and name then pet.actions[#pet.actions + 1] = name end
            end
        end
    end
    MacroForgeExport = { char = UnitName("player"), class = select(2, UnitClass("player")),
                         identity = raw, numMacros = { account = numAccount, char = numChar },
                         pet = pet, macros = macros, spells = spells }
    if not quiet then
        say(("exported %d spells, %d macros%s - /reload to write them to disk"):format(
            #spells, #macros, pet and (", pet " .. tostring(pet.family)) or ", no pet"))
    end
end

-- Slots: load-on-demand addons (MacroForge_S001...) that the client reads fresh from disk when they
-- are loaded. A slot can be loaded once per UI session and /reload resets them all.
-- macroforge.py `install` writes the same data into every slot because we cannot know which one
-- the client will load next.
local function slotName(i) return ("MacroForge_S%03d"):format(i) end

-- Loads the next unused slot. Returns its data and name, or nil and a message.
local function loadNextSlot()
    local ns = C_AddOns or {}
    local load = ns.LoadAddOn or LoadAddOn
    local exists = ns.DoesAddOnExist
    local isLoaded = ns.IsAddOnLoaded or IsAddOnLoaded
    if not load then return nil, "this client has no LoadAddOn" end
    local firstFree, total = nil, 0
    for i = 1, 200 do
        local name = slotName(i)
        if exists and not exists(name) then break end
        total = i
        if not firstFree and not (isLoaded and isLoaded(name)) then firstFree = name end
    end
    if total == 0 then
        return nil, "no slot addons found: run `python macroforge.py slots`, then fully restart WoW"
    end
    if not firstFree then
        return nil, ("all %d slots used this session - /reload to reset them"):format(total)
    end
    MacroForgeSlotData = nil
    local ok, reason = pcall(load, firstFree)
    local data = MacroForgeSlotData
    if not ok or type(data) ~= "table" then
        return nil, ("could not load %s%s"):format(firstFree,
            ok and " (data missing; restart WoW if the slots are new)" or (": " .. tostring(reason)))
    end
    return data, firstFree
end

-- /mf live: apply the newest macros WITHOUT a /reload.
local function liveApply()
    if InCombatLockdown() then note("in combat - try /mf live after the fight"); return end
    local data, name = loadNextSlot()
    if not data then note(name); return end
    if (data.rev or 0) == appliedRev then
        note(("no new macros (rev %s); used slot %s"):format(tostring(data.rev), name))
        return
    end
    applyAll(false, data, "live")
end

-- /mf ask <text>: draw the request as a strip of colored squares and take a screenshot; the PC-side
-- watcher reads the picture from the Screenshots folder. Then poll: every few seconds load a spare
-- slot and, once it carries the reply to this request, apply the macros and play a sound.
-- Only your own typed text is sent (500 characters at most).
local FIRST_CHECK, CHECK_EVERY, GIVE_UP = 12, 10, 180
local pollId = 0  -- the request being waited for; a newer request replaces an older poll
local pollWord = "macro"  -- what the pending request asked for: "macro" or "script"

local function fullName()
    local n, s = UnitName("player")
    if s and s ~= "" then return n .. " " .. s end
    return n
end

local function oneLine(s) return (tostring(s):gsub("%c+", " ")) end

-- "final" = the answer, "pending" = the watcher has the request and is still working on it
local function replyState(data, id)
    local state = nil
    for _, r in ipairs(list(data.replies)) do
        if type(r) == "table" and r.req == id then
            if not r.pending then return "final" end
            state = "pending"
        end
    end
    return state
end

-- The text of the final reply to this request, or nil. A reply that changed nothing starts with
-- "[No macro changes]" (the PC builds that part from the real diff), as it does for a question.
local function finalReply(data, id)
    for _, r in ipairs(list(data.replies)) do
        if type(r) == "table" and r.req == id and not r.pending and type(r.text) == "string" then
            return r.text
        end
    end
end

local function ping()
    pcall(PlaySound, (SOUNDKIT and SOUNDKIT.READY_CHECK) or 8960, "Master")
end

local function pollForReply(id, waited, told)
    if id ~= pollId then return end  -- replaced by a newer request
    told = told or {}
    if waited >= GIVE_UP then
        note("Still no answer. Check that the MacroForge watcher is running on your PC; /mf live fetches the reply later.")
        return
    end
    local delay = (waited == 0) and FIRST_CHECK or CHECK_EVERY
    C_Timer.After(delay, function()
        if id ~= pollId then return end
        if InCombatLockdown() then return pollForReply(id, waited + delay, told) end
        local data, why = loadNextSlot()
        if not data then
            note(why .. " - /mf live once the reply is ready")
            return
        end
        local state = replyState(data, id)
        if state == "final" then
            applyAll(false, data, "live")
            if (finalReply(data, id) or ""):sub(1, 19) == "[No macro changes] " then
                status("Done. Nothing was changed; see the chat window for the answer.")
            else
                status("Done. Your " .. pollWord .. " is ready (details in the chat window).")
            end
            ping()
            return
        end
        if state == "pending" and not told.working then
            told.working = true
            note("Your PC has the request and is working on it.")
        elseif not state and not told.silent then
            told.silent = true
            if pendingRequests() > 1 then  -- the PC answers one request at a time
                note("Your PC is still busy with an earlier request; this one is next. I'll keep checking.")
            else
                note("Your PC has not picked up the request yet. Is the MacroForge watcher running? I'll keep checking.")
            end
        end
        pollForReply(id, waited + delay, told)
    end)
end

local function askRequest(text, mode)
    mode = (mode == "script") and "script" or "macro"
    pollWord = mode
    text = strtrim(text or "")
    if text == "" then
        note(mode == "script" and "usage: /mf script <what the script should do, e.g. print my coordinates>"
             or "usage: /mf ask <what you want, e.g. a macro that casts X on mouseover>")
        return false
    end
    if #text > 500 then note("request too long (max 500 characters)"); return false end
    if type(MacroForgeRequests) ~= "table" then MacroForgeRequests = {} end
    local id = time() * 100
    local last = MacroForgeRequests[#MacroForgeRequests]
    if type(last) == "table" and type(last.id) == "number" and id <= last.id then
        id = last.id + 1  -- ids must be unique and increasing
    end
    local class = select(2, UnitClass("player"))
    local char = fullName()
    -- where new macros go: set by the window's checkbox (saved in MacroForgeUI), also used by /mf ask
    local scope = (type(MacroForgeUI) == "table" and MacroForgeUI.scope == "account") and "account" or "char"
    table.insert(MacroForgeRequests, { id = id, text = text, char = char, class = class,
                                       level = UnitLevel("player"), mode = mode, scope = scope })
    while #MacroForgeRequests > 10 do table.remove(MacroForgeRequests, 1) end
    recordRequest(id, mode, text, char)
    exportAll(true)  -- fresh spellbook + pet, written to disk at the next reload/logout
    local fields = { "MFREQ", id, UnitLevel("player"), class, oneLine(char), oneLine(text) }
    if scope == "account" then  -- the scope field follows the mode field
        fields[#fields + 1] = mode
        fields[#fields + 1] = "account"
    elseif mode == "script" then
        fields[#fields + 1] = "script"  -- macro requests for this character keep the old format
    end
    local payload = table.concat(fields, "\t")
    pollId = id
    MacroForgeStrip.Send(id, payload, function(ok, err)
        if not ok then
            note("could not take the screenshot: " .. tostring(err))
            return
        end
        note("Request sent. Your " .. mode .. " will be added automatically when it's ready.")
        pollForReply(id, 0)
    end)
    note("Sending your " .. (mode == "script" and "script request" or "request")
         .. (scope == "account" and " (for all your characters)" or "")
         .. " (colored squares flash briefly in the top-left corner)...")
    return true
end

-- Ideas: the checked macro ideas (for this class) and script examples from MacroForgeSuggestions.lua,
-- generated by macroforge.py. The window lists them; Add creates the macro. Class macros go on this
-- character (they use class spells); scripts are account-wide (any character can use them).
local function ideaValid(e)
    return validMacro(e) and type(e.why) == "string" and (e.level == nil or type(e.level) == "number")
end

function MacroForgeCore.ideas(mode)
    local data, source = MacroForgeSuggestions, nil
    if type(data) ~= "table" then return {} end
    if mode == "script" then source = data.scripts
    else source = list(data.macros)[select(2, UnitClass("player"))] end
    local out = {}
    for _, e in ipairs(list(source)) do
        if ideaValid(e) then out[#out + 1] = e end
    end
    return out
end

-- True if the player already has a macro with this idea's name where Add would put it.
function MacroForgeCore.ideaAdded(e)
    local account, char = scan()
    return ((e.script and account or char)[e.name]) ~= nil
end

function MacroForgeCore.addIdea(e)
    if not ideaValid(e) then note("that idea is damaged and was not added"); return false end
    if InCombatLockdown() then note("in combat - try again after the fight"); return false end
    if MacroForgeCore.ideaAdded(e) then
        note("you already have a macro named '" .. plain(e.name) .. "' (not changed)")
        return false
    end
    local perChar = not e.script
    local stats = { created = 0, updated = 0, removed = 0, failed = 0, scripts = 0 }
    applySafely({ name = e.name, icon = e.icon, body = e.body, script = e.script }, perChar, stats, "idea")
    if stats.created ~= 1 then
        status("Could not add it (see the chat window).")
        return false
    end
    if stats.scripts > 0 then scriptNotice() end
    note(("Added '%s' for %s. Find it in /macro and drag it to a bar."):format(
        plain(e.name), perChar and "this character" or "all your characters"))
    return true
end

-- /mf petcheck: with a pet out and an enemy targeted, print how the macro parser
-- evaluates the exact conditionals our pet macros use (Y = true, N = false).
local function petCheck()
    if not UnitExists("pet") then say("no pet out"); return end
    local fam, name = UnitCreatureFamily("pet"), UnitName("pet")
    say(("pet name=%s family=%s | target=%s"):format(tostring(name), tostring(fam), tostring(UnitName("target"))))
    local f = tostring(fam)
    local tests = {
        "[pet]", "[nopet]", "[pet:" .. f .. "]", "[pet:" .. tostring(name) .. "]",
        "[harm]", "[nodead]", "[harm,nodead]", "[@mouseover,harm,nodead]",
        "[pet:" .. f .. ",harm,nodead]",
        "[pet:" .. f .. ",@mouseover,harm,nodead][pet:" .. f .. ",harm,nodead]",
    }
    for _, opt in ipairs(tests) do
        local ok, action, unit = pcall(SecureCmdOptionParse, opt .. " Y; N")
        say(("  %s -> %s%s"):format(opt, ok and tostring(action) or "ERROR", unit and (" @" .. tostring(unit)) or ""))
    end
end

SLASH_MACROFORGE1 = "/mf"
SlashCmdList.MACROFORGE = function(arg)
    local askText = arg:match("^ask%s+(.*)$") or (arg == "ask" and "")
    local scriptText = arg:match("^script%s+(.*)$") or (arg == "script" and "")
    if askText then askRequest(askText)
    elseif scriptText then askRequest(scriptText, "script")
    elseif arg == "export" then exportAll()
    elseif arg == "probe" then MacroForge_Probe()
    elseif arg == "petcheck" then petCheck()
    elseif arg == "live" then liveApply()
    elseif arg == "ui" and MacroForgeCore.toggleWindow then MacroForgeCore.toggleWindow()
    elseif arg == "button" and MacroForgeCore.toggleButton then MacroForgeCore.toggleButton()
    else applyAll(false) end
end

MacroForgeCore.ask = askRequest
MacroForgeCore.live = liveApply
MacroForgeCore.export = exportAll
MacroForgeCore.petcheck = petCheck
MacroForgeCore.probe = function() MacroForge_Probe() end

local f = CreateFrame("Frame")
f:RegisterEvent("PLAYER_LOGIN")  -- also fires after /reload
f:SetScript("OnEvent", function()
    local ok, err = pcall(applyAll, true)  -- a damaged saved variable must not stop the login work
    if not ok then say("error while applying macros: " .. plain(err)) end
    local n = pendingRequests()
    if n > 0 then say(("%d request(s) waiting for the PC watcher; /mf live when it has answered"):format(n)) end
end)
